def planes(B):
    ev,evec=np.linalg.eig(B)
    out=[]
    for i in np.argsort(-np.abs(ev)):
        if ev[i].imag>1e-6:
            v=evec[:,i]; Q,_=np.linalg.qr(np.stack([v.real,v.imag],1)); out.append((ev[i],Q))
    return out
def angle_in_plane(B,Q):
    M=Q.T@B@Q
    sym=(M[0,0]+M[1,1])/2; anti=(M[1,0]-M[0,1])/2
    return np.degrees(np.arctan2(anti,sym)), np.hypot(sym,anti)
